// Normalise Typeform, Tally, Jotform, Calendly-style or plain JSON payloads into one lead shape
const pick = (o, keys) => { for (const k of Object.keys(o || {})) if (keys.some(x => k.toLowerCase().includes(x))) return o[k]; return ''; };
return $input.all().map(item => {
  const b = item.json.body || item.json; let src = 'form', f = {};
  if (b.form_response) { src = 'typeform'; for (const a of b.form_response.answers || []) { const label = (a.field?.ref || a.field?.title || a.type || '').toLowerCase(); f[label] = a.email || a.text || a.phone_number || a.number || a.choice?.label || ''; } }
  else if (b.data?.fields) { src = 'tally'; for (const x of b.data.fields) f[(x.label || x.key || '').toLowerCase()] = Array.isArray(x.value) ? x.value.join(', ') : x.value; }
  else if (b.rawRequest || b.formID) { src = 'jotform'; let r = b.rawRequest; try { r = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { r = {}; } for (const [k, v] of Object.entries(r || {})) f[k.toLowerCase()] = typeof v === 'object' ? Object.values(v).join(' ') : v; }
  else if (b.payload && (b.payload.email || b.payload.invitee)) { src = 'scheduler'; const p = b.payload.invitee || b.payload; f = { name: p.name, email: p.email, message: (b.payload.questions_and_answers || []).map(q => q.answer).join(' | ') }; }
  else { f = Object.fromEntries(Object.entries(b).map(([k, v]) => [k.toLowerCase(), v])); }
  const email = String(pick(f, ['email', 'mail']) || '').trim().toLowerCase();
  return { json: { name: pick(f, ['name']), email, phone: pick(f, ['phone', 'tel']), message: pick(f, ['message', 'need', 'comment', 'project', 'details']) || f.message || '', source: b.source || src } };
}).filter(i => i.json.email.includes('@'));
